32. const (
33. 	// ContainerTypeLabel describes container type.
34. 	ContainerTypeLabel = "ai.determined.container.type"
35. 	// ContainerTypeValue is the corresponding value for 'normal tasks'.
36. 	ContainerTypeValue = "task-container"
37. 	// ContainerVersionLabel describes the container version.
38. 	ContainerVersionLabel = "ai.determined.container.version"
39. 	// ContainerVersionValue is the current (and only) container version.
40. 	ContainerVersionValue = "0"
41. 	// ContainerIDLabel gives the Determined container ID (cproto.ID).
42. 	ContainerIDLabel = "ai.determined.container.id"
43. 	// ContainerDevicesLabel describes the devices allocated to the container.
44. 	ContainerDevicesLabel = "ai.determined.container.devices"
45. 	// ContainerDescriptionLabel describes the container.
46. 	ContainerDescriptionLabel = "ai.determined.container.description"
47. 	// AgentLabel gives the agent the container is managed by.
48. 	AgentLabel = "ai.determined.container.agent"
49. 	// ClusterLabel gives the cluster the container is managed by.
50. 	ClusterLabel = "ai.determined.container.cluster"
51. 	// MasterLabel gives the master the container is managed by.
52. 	MasterLabel = "ai.determined.container.master"
53. 
54. 	// ImagePullStatsKind describes the IMAGEPULL event.
55. 	ImagePullStatsKind = "IMAGEPULL"
56. )
