73. // Client wraps the Docker client, augmenting it with a few higher level convenience APIs.
74. type Client struct {
75. 	// Configuration details. Set during initialization, never modified afterwards.
76. 	credentialStores map[string]*credentialStore
77. 	authConfigs      map[string]types.AuthConfig
78. 
79. 	// System dependencies. Also set during initialization, never modified afterwards.
80. 	cl  *client.Client
81. 	log *logrus.Entry
82. }
83. 
84. // NewClient populates credentials from the Docker Daemon config and returns a new Client that uses
85. // them.
86. func NewClient(cl *client.Client) *Client {
87. 	d := &Client{
88. 		cl:  cl,
89. 		log: logrus.WithField("component", "docker-client"),
90. 	}
91. 
92. 	stores, auths, err := processDockerConfig()
93. 	if err != nil {
94. 		d.log.Infof("couldn't process ~/.docker/config.json %v", err)
95. 	}
96. 	if len(stores) == 0 {
97. 		d.log.Info("can't find any docker credential stores, continuing without them")
98. 	}
99. 	if len(auths) == 0 {
100. 		d.log.Info("can't find any auths in ~/.docker/config.json, continuing without them")
101. 	}
102. 	d.credentialStores, d.authConfigs = stores, auths
103. 
104. 	// hack: docker client library is not thread-safe when negotiating API Version
105. 	d.cl.NegotiateAPIVersion(context.TODO())
106. 	return d
107. }
108. 
109. // Inner returns the underlying Docker client, to be used sparingly.
110. // TODO(DET-8628): Consolidate around usage of the wrapper client, remove this.
111. func (d *Client) Inner() *client.Client {
112. 	return d.cl
113. }
114. 
115. // ReattachContainer looks for a single running or terminated container that matches the given
116. // filters and returns whether it can be reattached or has terminated.
117. func (d *Client) ReattachContainer(
118. 	ctx context.Context,
119. 	id cproto.ID,
120. ) (*Container, *aproto.ExitCode, error) {
121. 	filter := LabelFilter(ContainerIDLabel, id.String())
122. 	containers, err := d.cl.ContainerList(ctx, types.ContainerListOptions{Filters: filter})
123. 	if err != nil {
124. 		return nil, nil, fmt.Errorf("while reattaching container: %w", err)
125. 	}
126. 
127. 	if len(containers) > 1 {
128. 		return nil, nil, errors.New("reattach filters matched more than one container")
129. 	}
130. 
131. 	for _, cont := range containers {
132. 		// Subscribe to termination notifications first, to not miss immediate exits.
133. 		waiter, errs := d.cl.ContainerWait(ctx, cont.ID, dcontainer.WaitConditionNextExit)
134. 
135. 		// Restore containerInfo.
136. 		containerInfo, err := d.cl.ContainerInspect(ctx, cont.ID)
137. 		if err != nil {
138. 			return nil, nil, fmt.Errorf("inspecting reattached container: %w", err)
139. 		}
140. 
141. 		// Check if container has exited while we were trying to reattach it.
142. 		if !containerInfo.State.Running {
143. 			return nil, ptrs.Ptr(aproto.ExitCode(containerInfo.State.ExitCode)), nil
144. 		}
145. 		return &Container{ //nolint: staticcheck // We mean to terminate this loop.
146. 			ContainerInfo: containerInfo,
147. 			ContainerWaiter: ContainerWaiter{
148. 				Waiter: waiter,
149. 				Errs:   errs,
150. 			},
151. 		}, nil, nil
152. 	}
153. 	return nil, nil, nil
154. }
155. 
156. // PullImage describes a request to pull an image.
157. type PullImage struct {
158. 	Name      string
159. 	ForcePull bool
160. 	Registry  *types.AuthConfig
161. }
162. 
163. // PullImage pulls an image according to the given request and credentials initialized at client
164. // creation from the Daemon config or credentials helpers configured there. It takes a
165. // caller-provided channel on which docker events are sent. Slow receivers will block the call.
166. func (d *Client) PullImage(ctx context.Context, req PullImage, p events.Publisher[Event]) error {
167. 	ref, err := reference.ParseNormalizedNamed(req.Name)
168. 	if err != nil {
169. 		return fmt.Errorf("error parsing image name %s: %w", req.Name, err)
170. 	}
171. 	ref = reference.TagNameOnly(ref)
172. 	switch _, _, err = d.cl.ImageInspectWithRaw(ctx, ref.String()); {
173. 	case req.ForcePull:
174. 		if err != nil {
175. 			break
176. 		}
177. 
178. 		if err = p.Publish(ctx, NewLogEvent(model.LogLevelInfo, fmt.Sprintf(
179. 			"image present, but force_pull_image is set; checking for updates: %s",
180. 			ref.String(),
181. 		))); err != nil {
182. 			return err
183. 		}
184. 	case client.IsErrNotFound(err):
185. 		if err = p.Publish(ctx, NewLogEvent(model.LogLevelInfo, fmt.Sprintf(
186. 			"image not found, pulling image: %s", ref.String(),
187. 		))); err != nil {
188. 			return err
189. 		}
190. 	case err != nil:
191. 		return fmt.Errorf("error checking if image exists %s: %w", ref.String(), err)
192. 	default:
193. 		if err = p.Publish(ctx, NewLogEvent(model.LogLevelInfo, fmt.Sprintf(
194. 			"image already found, skipping pull phase: %s",
195. 			ref.String(),
196. 		))); err != nil {
197. 			return err
198. 		}
199. 		return nil
200. 	}
201. 
202. 	if err = p.Publish(ctx, NewBeginStatsEvent(ImagePullStatsKind)); err != nil {
203. 		return err
204. 	}
205. 	defer func() {
206. 		if scErr := p.Publish(ctx, NewEndStatsEvent(ImagePullStatsKind)); scErr != nil {
207. 			d.log.WithError(scErr).Warn("did not send image pull done stats")
208. 		}
209. 	}()
210. 
211. 	auth, err := d.getDockerAuths(ctx, ref, req.Registry, p)
212. 	if err != nil {
213. 		return fmt.Errorf("could not get docker authentication: %w", err)
214. 	}
215. 
216. 	authString, err := registryToString(*auth)
217. 	if err != nil {
218. 		return fmt.Errorf("error encoding docker credentials: %w", err)
219. 	}
220. 
221. 	logs, err := d.cl.ImagePull(ctx, ref.String(), types.ImagePullOptions{
222. 		All:          false,
223. 		RegistryAuth: authString,
224. 	})
225. 	if err != nil {
226. 		return errors.Wrapf(err, "error pulling image: %s", ref.String())
227. 	}
228. 	defer func() {
229. 		if err = logs.Close(); err != nil {
230. 			d.log.WithError(err).Error("error closing log stream")
231. 		}
232. 	}()
233. 
234. 	if err = d.sendPullLogs(ctx, logs, p); err != nil {
235. 		return fmt.Errorf("error processing pull log stream: %w", err)
236. 	}
237. 	return nil
238. }
239. 
240. // CreateContainer creates a container according to the given spec, returning a docker container ID
241. // to start it. It takes a caller-provided channel on which docker events are sent. Slow receivers
242. // will block the call.
243. func (d *Client) CreateContainer(
244. 	ctx context.Context,
245. 	id cproto.ID,
246. 	req cproto.RunSpec,
247. 	p events.Publisher[Event],
248. ) (string, error) {
249. 	response, err := d.cl.ContainerCreate(
250. 		ctx, &req.ContainerConfig, &req.HostConfig, &req.NetworkingConfig, nil, "")
251. 	if err != nil {
252. 		return "", fmt.Errorf("creating container: %w", err)
253. 	}
254. 	dockerID := response.ID
255. 	for _, w := range response.Warnings {
256. 		if err = p.Publish(ctx, NewLogEvent(model.LogLevelWarning, fmt.Sprintf(
257. 			"warning when creating container: %s", w,
258. 		))); err != nil {
259. 			return "", err
260. 		}
261. 	}
262. 
263. 	for _, copyArx := range req.Archives {
264. 		if err = p.Publish(ctx, NewLogEvent(model.LogLevelInfo, fmt.Sprintf(
265. 			"copying files to container: %s", copyArx.Path,
266. 		))); err != nil {
267. 			return "", err
268. 		}
269. 
270. 		files, cErr := archive.ToIOReader(copyArx.Archive)
271. 		if cErr != nil {
272. 			return "", fmt.Errorf("converting RunSpec Archive files to io.Reader: %w", cErr)
273. 		}
274. 		if err = d.cl.CopyToContainer(
275. 			ctx,
276. 			dockerID,
277. 			copyArx.Path,
278. 			files,
279. 			copyArx.CopyOptions,
280. 		); err != nil {
281. 			return "", fmt.Errorf("copying files to container: %w", err)
282. 		}
283. 	}
284. 	return dockerID, nil
285. }
286. 
287. // RunContainer runs a container by docker container ID. It takes a caller-provided channel on which
288. // docker events are sent. Slow receivers will block the call. RunContainer takes two contexts: one
289. // to govern cancellation of running the container, and another to govern the lifetime of the waiter
290. // returned.
291. // nolint: golint // Both contexts can't both be first.
292. func (d *Client) RunContainer(
293. 	ctx context.Context,
294. 	waitCtx context.Context,
295. 	id string,
296. 	p events.Publisher[Event],
297. ) (*Container, error) {
298. 	// Wait before start to not miss immediate exits.
299. 	waiter, errs := d.cl.ContainerWait(waitCtx, id, dcontainer.WaitConditionNextExit)
300. 
301. 	if err := d.cl.ContainerStart(ctx, id, types.ContainerStartOptions{}); err != nil {
302. 		return nil, fmt.Errorf("starting container: %w", err)
303. 	}
304. 
305. 	containerInfo, err := d.cl.ContainerInspect(ctx, id)
306. 	if err != nil {
307. 		if cErr := d.RemoveContainer(ctx, id, true); cErr != nil {
308. 			d.log.
309. 				WithError(cErr).
310. 				WithField("dcl-container-id", id).
311. 				Errorf("removing container %s after inspect failure", id)
312. 		}
313. 		return nil, fmt.Errorf("inspecting, container may be orphaned: %w", err)
314. 	}
315. 	return &Container{
316. 		ContainerInfo: containerInfo,
317. 		ContainerWaiter: ContainerWaiter{
318. 			Waiter: waiter,
319. 			Errs:   errs,
320. 		},
321. 	}, nil
322. }
323. 
324. // SignalContainer signals the container, by docker container ID, with the requested signal,
325. // returning an error if the Docker daemon is unable to process our request.
326. func (d *Client) SignalContainer(ctx context.Context, id string, sig syscall.Signal) error {
327. 	return d.cl.ContainerKill(ctx, id, unix.SignalName(sig))
328. }
329. 
330. // RemoveContainer removes a Docker container by ID.
331. func (d *Client) RemoveContainer(ctx context.Context, id string, force bool) error {
332. 	return d.cl.ContainerRemove(ctx, id, types.ContainerRemoveOptions{Force: force})
333. }
334. 
335. // ListRunningContainers lists running Docker containers satisfying the given filters.
336. func (d *Client) ListRunningContainers(ctx context.Context, fs filters.Args) (
337. 	map[cproto.ID]types.Container, error,
338. ) {
339. 	// List "our" running containers, based on `dockerAgentLabel`.
340. 	// This doesn't include containers spawned by other agents.
341. 	containers, err := d.cl.ContainerList(ctx, types.ContainerListOptions{All: false, Filters: fs})
342. 	if err != nil {
343. 		return nil, err
344. 	}
345. 
346. 	result := make(map[cproto.ID]types.Container, len(containers))
347. 	for _, cont := range containers {
348. 		containerID, ok := cont.Labels[ContainerIDLabel]
349. 		if ok {
350. 			result[cproto.ID(containerID)] = cont
351. 		} else {
352. 			d.log.Warnf("container %v has agent label but no container ID", cont.ID)
353. 		}
354. 	}
355. 	return result, nil
356. }
357. 
358. // LabelFilter is a convenience that takes a key and value and returns a docker label filter.
359. func LabelFilter(key, val string) filters.Args {
360. 	return filters.NewArgs(filters.Arg("label", key+"="+val))
361. }
362. 
363. func (d *Client) getDockerAuths(
364. 	ctx context.Context,
365. 	image reference.Named,
366. 	userRegistry *types.AuthConfig,
367. 	p events.Publisher[Event],
368. ) (*types.AuthConfig, error) {
369. 	imageDomain := reference.Domain(image)
370. 	// Try user submitted registry auth config.
371. 	if userRegistry != nil {
372. 		// TODO: remove didNotPassServerAddress when it becomes required.
373. 		didNotPassServerAddress := userRegistry.ServerAddress == ""
374. 		if didNotPassServerAddress {
375. 			if err := p.Publish(ctx, NewLogEvent(model.LogLevelWarning,
376. 				"setting registry_auth without registry_auth.serveraddress is deprecated "+
377. 					"and the latter will soon be required")); err != nil {
378. 				return nil, err
379. 			}
380. 		}
381. 
382. 		registryDomain := registry.ConvertToHostname(userRegistry.ServerAddress)
383. 		if registryDomain == imageDomain || didNotPassServerAddress {
384. 			return userRegistry, nil
385. 		}
386. 		if err := p.Publish(ctx, NewLogEvent(model.LogLevelWarning, fmt.Sprintf(
387. 			"not using expconfig registry_auth since expconf "+
388. 				"registry_auth.serverAddress %s did not match the image serverAddress %s",
389. 			registryDomain, imageDomain,
390. 		))); err != nil {
391. 			return nil, err
392. 		}
393. 	}
394. 
395. 	// Try using credential stores specified in ~/.docker/config.json.
396. 	if store, ok := d.credentialStores[imageDomain]; ok {
397. 		creds, err := store.get()
398. 		if err != nil {
399. 			return nil, fmt.Errorf("unable to get credentials from helper: %w", err)
400. 		}
401. 
402. 		if err := p.Publish(ctx, NewLogEvent(model.LogLevelInfo, fmt.Sprintf(
403. 			"domain '%s' found in 'credHelpers' config, using credentials helper",
404. 			imageDomain,
405. 		))); err != nil {
406. 			return nil, err
407. 		}
408. 
409. 		return &creds, nil
410. 	}
411. 
412. 	// Finally try using auths section of user's ~/.docker/config.json.
413. 	index, err := registry.ParseSearchIndexInfo(image.String())
414. 	if err != nil {
415. 		return nil, fmt.Errorf("error invalid docker repo name: %w", err)
416. 	}
417. 	reg := registry.ResolveAuthConfig(d.authConfigs, index)
418. 	if reg == (types.AuthConfig{}) {
419. 		return &reg, nil
420. 	}
421. 
422. 	if err := p.Publish(ctx, NewLogEvent(model.LogLevelInfo, fmt.Sprintf(
423. 		"domain '%s' found in 'auths' ~/.docker/config.json", imageDomain,
424. 	))); err != nil {
425. 		return nil, err
426. 	}
427. 	return &reg, nil
428. }
429. 
430. // registryToString converts the Registry struct to a base64 encoding for json strings.
431. func registryToString(reg types.AuthConfig) (string, error) {
432. 	// Docker stores the username and password in an auth section types.AuthConfig
433. 	// formatted as user:pass then base64ed. This is not documented clearly.
434. 	// https://github.com/docker/cli/blob/master/cli/config/configfile/file.go#L76
435. 	if reg.Auth != "" {
436. 		bytes, err := base64.StdEncoding.DecodeString(reg.Auth)
437. 		if err != nil {
438. 			return "", err
439. 		}
440. 		userAndPass := strings.SplitN(string(bytes), ":", 2)
441. 		if len(userAndPass) != 2 {
442. 			return "", errors.Errorf("auth field of docker authConfig must be base64ed user:pass")
443. 		}
444. 		reg.Username, reg.Password = userAndPass[0], userAndPass[1]
445. 		reg.Auth = ""
446. 	}
447. 	bs, err := json.Marshal(reg)
448. 	if err != nil {
449. 		return "", err
450. 	}
451. 
452. 	return base64.URLEncoding.EncodeToString(bs), nil
453. }
454. 
455. func (d *Client) sendPullLogs(ctx context.Context, r io.Reader, p events.Publisher[Event]) error {
456. 	plf := pullLogFormatter{Known: map[string]*pullInfo{}}
457. 
458. 	scanner := bufio.NewScanner(r)
459. 	for scanner.Scan() {
460. 		log := jsonmessage.JSONMessage{}
461. 		if err := json.Unmarshal(scanner.Bytes(), &log); err != nil {
462. 			return fmt.Errorf("error parsing log message: %#v: %w", log, err)
463. 		}
464. 
465. 		logMsg := plf.Update(log)
466. 		if logMsg == nil {
467. 			continue
468. 		}
469. 
470. 		if err := p.Publish(ctx, NewLogEvent(model.LogLevelInfo, *logMsg)); err != nil {
471. 			return err
472. 		}
473. 	}
474. 	// Always print the complete progress bar, regardless of the backoff time.
475. 	finalLogMsg := plf.RenderProgress()
476. 	if err := p.Publish(ctx, NewLogEvent(model.LogLevelInfo, finalLogMsg)); err != nil {
477. 		return err
478. 	}
479. 	return scanner.Err()
480. }
